+// VerifyDLL.cpp : Verification of an Authenticode signed DLL
+//
+
+#include <memory>
+#include <windows.h>
+#include <wintrust.h>
+#include <softpub.h>
+#include <wincrypt.h>
+#include <sensapi.h>
